fn on_block_broken(player, block) -> (
    text.send(player, 'you broke ' + block);
    false           // true = the breaking is cancelled
);

event.on('player_breaks_block', on_block_broken);

// a loop that lets the world go on between rounds
fn step(n) -> (
    work(n);
    if(n < 100, event.schedule(1, step, n + 1))
);
step(0);
